```python
notes = []

def create_note():
    content = input("Nhập nội dung ghi chú: ")
    notes.append(content)
    print("Ghi chú đã được tạo thành công.")

def view_notes():
    if len(notes) == 0:
        print("Không có ghi chú nào.")
    else:
        for i, note in enumerate(notes, start=1):
            print(f"Ghi chú {i}: {note}")

def delete_note():
    if len(notes) == 0:
        print("Không có ghi chú nào để xóa.")
    else:
        view_notes()
        choice = int(input("Nhập số thứ tự của ghi chú bạn muốn xóa: "))
        if 1 <= choice <= len(notes):
            deleted_note = notes.pop(choice - 1)
            print(f"Ghi chú {choice} đã được xóa: {deleted_note}")
        else:
            print("Số thứ tự không hợp lệ.")

while True:
    print("Chọn tác vụ:")
    print("1. Tạo ghi chú mới")
    print("2. Xem tất cả các ghi chú")
    print("3. Xóa ghi chú")
    print("4. Thoát")
    choice = int(input("Nhập số tương ứng với tác vụ bạn muốn thực hiện: "))

    if choice == 1:
        create_note()
    elif choice == 2:
        view_notes()
    elif choice == 3:
        delete_note()
    elif choice == 4:
        break
    else:
        print("Lựa chọn không hợp lệ. Vui lòng chọn lại.")
```

